"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$zip = '"'C:\\Users\\hzq00\\Downloads\\HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE.zip'
"'$inEntry = '"'HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE/source/VER_AN10_PACKAGES_INPUT.txt'
"'$seedEntry = '"'HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE/03_PACKAGE_POLICY_SEED.tsv'
"'$inLines = @(tar -xOf $zip $inEntry | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '"'' })
"'$seedLines = @(tar -xOf $zip $seedEntry)

$seed = @{}; $seedOrder = New-Object System.Collections.Generic.List[string]
$hdr = $true
foreach ($line in $seedLines) {
  if ($hdr) { $hdr = $false; continue }
  if ($line.Trim() -eq '"'') { continue }
  "'$parts = $line -split "`t"
  if ($parts.Count -lt 3) { Write-Output ("BADROW: " + $line); continue }
  $pkg = $parts[0].Trim()
  $seed[$pkg] = @{ layer = $parts[1].Trim(); policy = $parts[2].Trim(); note = $(if ($parts.Count -gt 3) { $parts[3].Trim() } else { '"'' }) }
  "'$seedOrder.Add($pkg)
}

$unique = $inLines | Sort-Object -Unique
$dups = $inLines | Group-Object | Where-Object { $_.Count -gt 1 } | Sort-Object Name

Write-Output "=== INPUT COUNTS ==="
Write-Output ("total_lines=" + $inLines.Count)
Write-Output ("unique=" + $unique.Count)
Write-Output ("duplicate_names=" + ($dups | Measure-Object).Count)
$dups | ForEach-Object { Write-Output ("DUP " + $_.Name + " x" + $_.Count) }

Write-Output "=== SEED COUNTS ==="
Write-Output ("seed_rows=" + $seedOrder.Count)
Write-Output ("seed_unique=" + (($seedOrder | Sort-Object -Unique).Count))
($seedOrder | Group-Object | Where-Object { $_.Count -gt 1 } | Sort-Object Name) | ForEach-Object { Write-Output ("SEEDDUP " + $_.Name + " x" + $_.Count) }

Write-Output "=== SET OPS ==="
$inSeed = @($unique | Where-Object { $seed.ContainsKey($_) })
$missing = @($unique | Where-Object { -not $seed.ContainsKey($_) })
$seedOnly = @($seedOrder | Sort-Object -Unique | Where-Object { $_ -notin $unique })
Write-Output ("input_in_seed=" + $inSeed.Count)
Write-Output ("input_missing_from_seed=" + $missing.Count)
Write-Output ("seed_not_in_input=" + $seedOnly.Count)
Write-Output "--- MISSING (input - seed) ---"
$missing | ForEach-Object { Write-Output $_ }
Write-Output "--- SEEDONLY (seed - input) ---"
$seedOnly | ForEach-Object { Write-Output $_ }

Write-Output "=== LAYER DISTRIBUTION (input in seed) ==="
$inSeed | ForEach-Object { $seed[$_].layer } | Group-Object | Sort-Object Name | ForEach-Object { Write-Output ($_.Name + "`t" + $_.Count) }
Write-Output "=== POLICY DISTRIBUTION (input in seed) ==="
$inSeed | ForEach-Object { $seed[$_].policy } | Group-Object | Sort-Object Name | ForEach-Object { Write-Output ($_.Name + "`t" + $_.Count) }

Write-Output "=== MISSING-LAYER HEURISTIC ==="
$sysRe = '"'"'^(com'"\\.android|com\\.google\\.android|com\\.qualcomm|com\\.qti|vendor\\.|androidhnext|android|org\\.codeaurora)'
foreach ("'$p in ($missing | Sort-Object)) {
  if ($p -match $sysRe) { $c = '"'SYSTEM_LIKE' } elseif ("'$p -match '"'"'^com'"\\.hihonor|"'^com'"\\.honor|"'^com'"\\.huawei') { "'$c = '"'OEM_LIKE' } else { "'$c = '"'THIRD_PARTY' }
  Write-Output ("'$c + "`t" + $p)
}'

