Write-Output "=== CANDIDATES ==="
$inLines | Sort-Object -Unique | Where-Object { $seed[$_].policy -match '"'UAD_DISABLE|UNINSTALL_CANDIDATE|"'^REVIEW$|KEEP_ALREADY_DISABLED'"' } | ForEach-Object { "'$s = $seed[$_]; Write-Output ($s.policy + "`t" + $s.layer + "`t" + $_ + "`t" + $s.note) }
Write-Output "=== FORMAT CHECK ==="
$bad = $inLines | Where-Object { $_ -notmatch '"'"'^[A-Za-z_][A-Za-z0-9_.]*$'"' }
Write-Output (\"invalid_package_names=\" + "'$bad.Count)
$bad | ForEach-Object { Write-Output ("BAD: " + $_) }
$long = $inLines | Where-Object { $_.Length -gt 100 }
Write-Output ("names_over_100_chars=" + $long.Count)
Write-Output "=== EDGE NAMES ==="
($inLines | Sort-Object | Select-Object -First 5) | ForEach-Object { Write-Output $_ }
($inLines | Sort-Object | Select-Object -Last 5) | ForEach-Object { Write-Output $_ }'

